import os


def read_names(path):
    names = {}
    with open(path, encoding="utf-8") as f:
        for line in f:
            name = line.strip()
            if not name:
                continue
            key = name.casefold()
            if key not in names:
                names[key] = name
    return names


def fmt(items):
    if not items:
        return "—"
    return ", ".join(sorted(items, key=lambda s: (s.casefold(), s)))


